   "css": "\n:root {\n  --font-sans: 'Cairo', sans-serif;\n  --font-mono: 'Consolas', 'Courier New', monospace;\n  --success: #16a34a;\n  --success-bg: #f0fdf4;\n  --success-text: #16a34a;\n  --success-border: #bbf7d0;\n  --warning: #c2410c;\n  --warning-bg: #fff7ed;\n  --warning-text: #c2410c;\n  --warning-border: #fed7aa;\n  --danger: #b91c1c;\n  --danger-bg: #fef2f2;\n  --danger-text: #b91c1c;\n  --danger-border: #fecaca;\n  --info: #0369a1;\n  --amber: #b45309;\n  --brand-primary: #111111;\n  --brand-primary-hover: #000000;\n  --brand-subtle-bg: #fef08a;\n  --brand-border: #111111;\n  --btn-text-color: #fbbf24;\n  --shadow-brand: 0 4px 14px rgba(17, 17, 17, 0.25);\n}\n.topbar { background: #111111; border-bottom: 1px solid #111111; }\n.topbar .nav-item { color: #fbbf24; }\n.topbar .nav-item:hover, .topbar .nav-item.active { color: #111111; background: #fbbf24; }\n/* TopLight dropdowns: curved black fill, yellow ink + black-on-yellow hover — always apparent.\n   Scoped to .topbar so a dropdown rendered in page content keeps the neutral surface. */\n.topbar .nav-dropdown-menu {\n  background: #111111;\n  border: 1px solid #fbbf24;\n  border-radius: 16px;\n  box-shadow: 0 12px 28px rgba(0,0,0,.45);\n}\n.topbar .nav-dropdown-toggle { color: #fbbf24; }\n.topbar .nav-dropdown-toggle:hover, .topbar .nav-dropdown-toggle.open { color: #111111; background: #fbbf24; }\n/* Profile toggle must read without hovering: pill button + yellow name (the .user-name\n   rule would otherwise paint it near-black on the black topbar) */\n.topbar .user-profile-toggle { border: 1px solid #fbbf24; border-radius: 999px; padding: 4px 12px; background: #111111; }\n.topbar .user-profile-toggle .user-name { color: #fbbf24; }\n.topbar .user-profile-toggle .nav-dropdown-caret { color: #fbbf24; }\n.topbar .user-profile-toggle:hover, .topbar .user-profile-toggle.open { background: #fbbf24; }\n.topbar .user-profile-toggle:hover .user-name, .topbar .user-profile-toggle.open .user-name,\n.topbar .user-profile-toggle:hover .nav-dropdown-caret, .topbar .user-profile-toggle.open .nav-dropdown-caret { color: #111111; }\n.topbar .nav-dropdown-item { color: #fbbf24; font-weight: 700; border-radius: 10px; }\n.topbar .nav-dropdown-item:hover { background: #fbbf24; color: #111111; }\n.topbar .nav-dropdown-item-active { background: #fbbf24; color: #111111; font-weight: 800; }\n.topbar .user-avatar { background: #fbbf24; color: #111111; }\n.topbar .user-profile-name { color: #fbbf24; }\n.topbar .user-profile-email { color: #fde68a; }\n.topbar .user-profile-divider { background: #fbbf24; opacity: .4; }\n.topbar .user-profile-logout { color: #fbbf24; }\n.topbar .user-profile-logout:hover { background: #fbbf24; color: #111111; }\n/* Mobile hamburger: black bars are invisible on the black topbar — yellow instead */\n.topbar-hamburger { border: 1px solid #fbbf24; }\n.topbar-hamburger .hamburger-bar { background: #fbbf24; }\n.invoice { background: #ffffff; border: 1px solid var(--border-color); }\n"
