   "css": "\n:root {\n  --font-sans: 'Cairo', sans-serif;\n  --font-mono: 'Consolas', 'Courier New', monospace;\n  --success: #16a34a;\n  --success-bg: #f0fdf4;\n  --success-text: #16a34a;\n  --success-border: #bbf7d0;\n  --warning: #b45309;\n  --warning-bg: #fffbeb;\n  --warning-text: #b45309;\n  --warning-border: #fde68a;\n  --danger: #b91c1c;\n  --danger-bg: #fef2f2;\n  --danger-text: #b91c1c;\n  --danger-border: #fecaca;\n  --info: #0369a1;\n  --amber: #b45309;\n  --brand-primary: #16a34a;\n  --brand-primary-hover: #15803d;\n  --brand-subtle-bg: #dcfce7;\n  --brand-border: #16a34a;\n  --btn-text-color: #ffffff;\n  --shadow-brand: 0 4px 14px rgba(22, 163, 74, 0.25);\n}\n.topbar { background: #15803d; border-bottom: 1px solid #14532d; }\n.topbar .nav-item { color: #ffffff; }\n.topbar .nav-item:hover, .topbar .nav-item.active { color: #15803d; background: #ffffff; }\n.topbar .nav-dropdown-toggle { color: #ffffff; }\n.topbar .nav-dropdown-toggle:hover, .topbar .nav-dropdown-toggle.open { color: #15803d; background: #ffffff; }\n.topbar .nav-dropdown-menu { background: #ffffff; border: 1px solid var(--border-color); }\n.topbar .nav-dropdown-item:hover { background: #dcfce7; color: #15803d; }\n/* Profile toggle must read without hovering: the shared .user-name rule\n   would otherwise paint it near-black on the green topbar. */\n.topbar .user-profile-toggle { border: 1px solid #ffffff; border-radius: 999px; padding: 4px 12px; }\n.topbar .user-profile-toggle .user-name { color: #ffffff; }\n.topbar .user-profile-toggle .nav-dropdown-caret { color: #ffffff; }\n.topbar .user-profile-toggle:hover, .topbar .user-profile-toggle.open { background: #ffffff; }\n.topbar .user-profile-toggle:hover .user-name, .topbar .user-profile-toggle.open .user-name,\n.topbar .user-profile-toggle:hover .nav-dropdown-caret, .topbar .user-profile-toggle.open .nav-dropdown-caret { color: #15803d; }\n.topbar .user-avatar { background: #ffffff; color: #15803d; }\n/* Mobile hamburger: dark bars are invisible on the green topbar. */\n.topbar-hamburger { border: 1px solid #ffffff; }\n.topbar-hamburger .hamburger-bar { background: #ffffff; }\n.btn-primary { background: #15803d; box-shadow: 0 4px 14px rgba(20, 83, 45, 0.3); }\n.btn-primary:hover { background: #14532d; box-shadow: 0 6px 16px rgba(20, 83, 45, 0.35); }\n.btn-outline:hover { background: #dcfce7; border-color: #15803d; color: #14532d; }\n.invoice { background: #ffffff; border: 1px solid var(--border-color); }\n"
